// 只隔离原死因读取的严格单步边界；不冒实际军战死亡或自然清算世界。
#include "resident/domains/commerce/liquidation/private_shop_liquidation_detail.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
int main(){try{
 int checks=0;auto check=[&](bool ok,const char* label){++checks;if(!ok)throw std::runtime_error(label);};auto catalog=std::make_shared<CommonCatalog>();CommonStore common{CommonState{},catalog};PrivateShopState shops;PrivateShopCatalog shop_catalog;PrivateShopLiquidationState mandates;PrivateShopLiquidationCatalog policies;InteractionCatalog interaction;FamilyDeathState deaths;ActorRecord actor;actor.id="owner";actor.alive=actor.available=true;common.state().actors.insert(actor.id,actor);
 auto append=[&](const StableId& prefix,const StableId& kind,const StableId& domain){auto id=common.next_id(prefix);check(id.ok&&common.append_fact({id.value,kind,domain}).ok,"real Common source allocation");return id.value;};
 auto old=append("private_shop_executor","private_shop_executor_appointed","private_shop_liquidations");auto cause=append("military","military_casualties","military");common.state().actors.find(actor.id)->alive=false;
 std::optional<FamilyDeathOrigin> death=FamilyDeathOrigin{actor.id,cause,"battle.source",1};FamilyDeathOriginRead read=[&](const StableId& who)->Outcome<std::optional<FamilyDeathOrigin>>{return {true,who==actor.id?death:std::nullopt,{}};};PrivateShopLiquidationContext context{common,*catalog,shops,shop_catalog,mandates,policies,interaction,deaths,read,{}};
 check(!shop_liquidation_detail::alive_before(context,actor.id,0,old).ok,"cold committed clock refuses future cause");DynamicStepInput phase;phase.from_tick=0;phase.to_tick=1;context.phase=&phase;check(shop_liquidation_detail::alive_before(context,actor.id,0,old).ok,"real single phase preserves old signature before later death");check(!shop_liquidation_detail::alive_before(context,actor.id,0).ok,"phase cannot grant a current new signature");phase.to_tick=2;check(!shop_liquidation_detail::alive_before(context,actor.id,0,old).ok,"multi-step phase rejected");phase.from_tick=1;phase.to_tick=2;check(!shop_liquidation_detail::alive_before(context,actor.id,0,old).ok,"wrong phase origin rejected");context.phase=nullptr;common.state().identity.tick=1;check(shop_liquidation_detail::alive_before(context,actor.id,0,old).ok,"post-clock old signature retained");auto later=append("private_shop_executor","private_shop_executor_appointed","private_shop_liquidations");check(!shop_liquidation_detail::alive_before(context,actor.id,1,later).ok,"actual death before later signature rejected");death.reset();check(!shop_liquidation_detail::alive_before(context,actor.id,0,old).ok,"dead actor missing actual source stays unavailable");std::cout<<checks<<"/0 strict old-signature phase checks\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
